#include <bits/stdc++.h>
using namespace std;

long long pow_mod(long long base, long long exp) {
    long long res=1;
    while (exp>0) {
        if (exp & 1) res=(res*base)%1000000007;
        base=(base*base)%1000000007;
        exp>>=1;
    }
    return res;
}

struct UnionFind {
    vector<int> parent, rank;
    int count;
    UnionFind(int n): parent(n), rank(n,0), count(n) {
        for (int i=0; i<n; ++i) parent[i]=i;
    }
    int find(int u) {
        if (parent[u]!=u) parent[u]=find(parent[u]);
        return parent[u];
    }
    void unite(int u, int v) {
        u=find(u); v=find(v);
        if (u!=v) {
            if (rank[u]<rank[v]) swap(u,v);
            parent[v]=u;
            if (rank[u]==rank[v]) ++rank[u];
            --count;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long p, k;
    cin>>p>>k;
    vector<bool> visited(p,false);
    UnionFind uf(p);
    for (long long i=0; i<p; ++i) {
        for (long long j=i; !visited[j]; j=(j*k)%p) {
            visited[j]=true;
            uf.unite(i,j);
        }
    }
    int c=uf.count;
    if (k!=1) c--;
    cout<<pow_mod(p,c)<<endl;
    return 0;
}
